package com.andye.warmod.phalanx.client.gui;
import com.andye.warmod.menu.PhalanxMenu;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.inventory.Slot;
public final class PhalanxScreen extends AbstractContainerScreen<PhalanxMenu>{public PhalanxScreen(PhalanxMenu m,Inventory i,Component t){super(m,i,t,176,166);}@Override public void extractRenderState(GuiGraphicsExtractor g,int mouseX,int mouseY,float partial){g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xff20262a);g.fill(leftPos+36,topPos+27,leftPos+140,topPos+62,0xff0d1113);for(Slot slot:menu.slots){int x=leftPos+slot.x-1,y=topPos+slot.y-1;g.fill(x,y,x+18,y+18,0xff68757a);g.fill(x+1,y+1,x+17,y+17,0xff0b1114);}super.extractRenderState(g,mouseX,mouseY,partial);var turret=menu.turret();if(turret!=null){g.text(font,Component.literal("Rounds: "+turret.rounds()),leftPos+8,topPos+18,0xffe0b34a);g.text(font,Component.literal(turret.status().name().replace('_',' ')),leftPos+8,topPos+65,0xff8fd5b5);g.text(font,Component.literal(String.format(java.util.Locale.ROOT,"Bloom %.2f",turret.bloom())),leftPos+92,topPos+65,0xffb9c1c5);}}}